<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>아로마 카페 - 메뉴</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: linear-gradient(135deg, #f5e6d3 0%, #e8d4c4 100%);
            padding: 20px;
            min-height: 100vh;
        }

        .container {
            max-width: 1000px;
            margin: 0 auto;
            background: white;
            border-radius: 15px;
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.1);
            overflow: hidden;
        }

        .header {
            background: linear-gradient(135deg, #8b6f47 0%, #a0826d 100%);
            color: white;
            padding: 40px 20px;
            text-align: center;
        }

        .header h1 {
            font-size: 2.5em;
            margin-bottom: 10px;
            font-weight: 700;
        }

        .header p {
            font-size: 1.1em;
            opacity: 0.9;
        }

        .content {
            padding: 40px 20px;
        }

        .menu-section {
            margin-bottom: 40px;
        }

        .section-title {
            font-size: 1.8em;
            color: #8b6f47;
            margin-bottom: 20px;
            padding-bottom: 10px;
            border-bottom: 3px solid #d4a574;
        }

        .menu-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 20px;
        }

        .menu-item {
            background: #f9f7f4;
            padding: 20px;
            border-radius: 10px;
            border-left: 4px solid #d4a574;
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .menu-item:hover {
            transform: translateY(-5px);
            box-shadow: 0 8px 20px rgba(139, 111, 71, 0.15);
        }

        .menu-item-name {
            font-size: 1.3em;
            color: #333;
            margin-bottom: 8px;
            font-weight: 600;
        }

        .menu-item-description {
            font-size: 0.95em;
            color: #666;
            margin-bottom: 12px;
            line-height: 1.5;
        }

        .menu-item-price {
            font-size: 1.4em;
            color: #8b6f47;
            font-weight: 700;
        }

        .footer {
            background: #f5e6d3;
            padding: 20px;
            text-align: center;
            color: #666;
            font-size: 0.95em;
        }

        @media (max-width: 600px) {
            .header h1 {
                font-size: 1.8em;
            }

            .menu-grid {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>
